#include <algorithm>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>
using namespace std;
class Person{protected:int id;string name;public:Person(int i=0,string n=""):id(i),name(move(n)){}virtual~Person()=default;int getId()const{return id;}const string& getName()const{return name;}virtual void print()const{cout<<id<<" | "<<name;}};
class Patient:public Person{int age{};string gender,contact;vector<string>history;public:Patient(int i=0,string n="",int a=0,string g="",string c=""):Person(i,move(n)),age(a),gender(move(g)),contact(move(c)){}void addHistory(string x){history.push_back(move(x));}void print()const override{Person::print();cout<<" | age "<<age<<" | "<<gender<<" | "<<contact<<"\n";for(auto&h:history)cout<<"  history: "<<h<<'\n';}string data()const{ostringstream o;o<<id<<'|'<<name<<'|'<<age<<'|'<<gender<<'|'<<contact;return o.str();}};
class Doctor:public Person{string specialty;double fee{};vector<string>slots;public:Doctor(int i=0,string n="",string s="",double f=0):Person(i,move(n)),specialty(move(s)),fee(f){}double getFee()const{return fee;}void print()const override{Person::print();cout<<" | "<<specialty<<" | fee "<<fee<<'\n';}string data()const{ostringstream o;o<<id<<'|'<<name<<'|'<<specialty<<'|'<<fee;return o.str();}};
struct Appointment{int id,patientId,doctorId;string date,time,status="Scheduled";string data()const{return to_string(id)+"|"+to_string(patientId)+"|"+to_string(doctorId)+"|"+date+"|"+time+"|"+status;}};
class Hospital{vector<Patient>patients;vector<Doctor>doctors;vector<Appointment>apps;int nextApp=1;Patient*pfind(int id){for(auto&p:patients)if(p.getId()==id)return&p;return nullptr;}Doctor*dfind(int id){for(auto&d:doctors)if(d.getId()==id)return&d;return nullptr;}bool conflict(int did,const string&d,const string&t)const{for(auto&a:apps)if(a.doctorId==did&&a.date==d&&a.time==t&&a.status=="Scheduled")return true;return false;}public:void load(){string l;ifstream p("patients.txt");while(getline(p,l)){stringstream s(l);string a,b,c,d,e;getline(s,a,'|');getline(s,b,'|');getline(s,c,'|');getline(s,d,'|');getline(s,e);if(!a.empty())patients.emplace_back(stoi(a),b,stoi(c),d,e);}ifstream dr("doctors.txt");while(getline(dr,l)){stringstream s(l);string a,b,c,d;getline(s,a,'|');getline(s,b,'|');getline(s,c,'|');getline(s,d);if(!a.empty())doctors.emplace_back(stoi(a),b,c,stod(d));}ifstream ap("appointments.txt");while(getline(ap,l)){stringstream s(l);string a,b,c,d,e,f;getline(s,a,'|');getline(s,b,'|');getline(s,c,'|');getline(s,d,'|');getline(s,e,'|');getline(s,f);if(!a.empty()){apps.push_back({stoi(a),stoi(b),stoi(c),d,e,f});nextApp=max(nextApp,stoi(a)+1);}}}void save()const{ofstream p("patients.txt");for(auto&x:patients)p<<x.data()<<'\n';ofstream d("doctors.txt");for(auto&x:doctors)d<<x.data()<<'\n';ofstream a("appointments.txt");for(auto&x:apps)a<<x.data()<<'\n';}void addPatient(){int id,age;string n,g,c;cout<<"ID: ";cin>>id;if(pfind(id)){cout<<"Duplicate.\n";return;}cout<<"Name: ";cin>>ws;getline(cin,n);cout<<"Age: ";cin>>age;cout<<"Gender: ";cin>>g;cout<<"Contact: ";cin>>c;patients.emplace_back(id,n,age,g,c);}void addDoctor(){int id;double fee;string n,s;cout<<"ID: ";cin>>id;if(dfind(id))return;cout<<"Name: ";cin>>ws;getline(cin,n);cout<<"Specialty: ";getline(cin,s);cout<<"Consultation fee: ";cin>>fee;doctors.emplace_back(id,n,s,fee);}void schedule(){int p,d;string date,time;cout<<"Patient ID Doctor ID: ";cin>>p>>d;if(!pfind(p)||!dfind(d)){cout<<"Invalid patient/doctor.\n";return;}cout<<"Date Time: ";cin>>date>>time;if(conflict(d,date,time)){cout<<"Doctor already booked.\n";return;}apps.push_back({nextApp++,p,d,date,time,"Scheduled"});}void cancel(){int id;cin>>id;for(auto&a:apps)if(a.id==id){a.status="Cancelled";return;}}void complete(){int id;cout<<"Appointment ID: ";cin>>id;for(auto&a:apps)if(a.id==id){a.status="Completed";string note;cout<<"Medical history entry: ";cin>>ws;getline(cin,note);if(auto*p=pfind(a.patientId))p->addHistory(note);return;}}void bill(){int id;cout<<"Appointment ID: ";cin>>id;for(auto&a:apps)if(a.id==id){auto*d=dfind(a.doctorId);double extra;cout<<"Additional charges: ";cin>>extra;cout<<"Bill total: "<<(d?d->getFee():0)+max(0.0,extra)<<'\n';return;}}void view()const{for(auto&p:patients)p.print();for(auto&d:doctors)d.print();for(auto&a:apps)cout<<a.id<<" | P"<<a.patientId<<" D"<<a.doctorId<<" | "<<a.date<<' '<<a.time<<" | "<<a.status<<'\n';}void run(){load();for(;;){cout<<"\nHospital\n1 Add patient 2 Add doctor 3 Schedule 4 Cancel 5 Complete 6 Bill 7 View 0 Exit\nChoice: ";int c;if(!(cin>>c)||c==0){save();break;}if(c==1)addPatient();else if(c==2)addDoctor();else if(c==3)schedule();else if(c==4)cancel();else if(c==5)complete();else if(c==6)bill();else if(c==7)view();save();}}};int main(){Hospital{}.run();}
